create table public.dm_narrations(id uuid primary key default gen_random_uuid(),table_id uuid not null references public.dice_tables(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,dm_name text not null,narration text not null check(char_length(narration) between 1 and 5000),created_at timestamptz not null default now());
create index dm_narrations_table_idx on public.dm_narrations(table_id,created_at desc);alter table public.dm_narrations enable row level security;
create policy "Room members can read DM narration" on public.dm_narrations for select to authenticated using(public.is_dice_table_member(table_id));
create or replace function public.publish_dm_narration(target_table_id uuid,target_narration text)
returns public.dm_narrations language plpgsql security definer set search_path='' as $$declare member public.dice_table_members%rowtype;result public.dm_narrations%rowtype;clean text;begin select * into member from public.dice_table_members where table_id=target_table_id and user_id=auth.uid() and role='dm';if member.user_id is null then raise exception 'dm required';end if;clean:=trim(target_narration);if char_length(clean)<1 or char_length(clean)>5000 then raise exception 'invalid narration';end if;insert into public.dm_narrations(table_id,user_id,dm_name,narration)values(target_table_id,auth.uid(),member.display_name,clean)returning * into result;return result;end;$$;
revoke all on function public.publish_dm_narration(uuid,text) from public;grant execute on function public.publish_dm_narration(uuid,text) to authenticated;alter publication supabase_realtime add table public.dm_narrations;
